// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0) && sender != address(c));
        vm.assume(amount > 0 && amount <= type(uint256).max);

        // Open the contract to public
        c.OpenToThePublic();

        // Set bet limit to amount
        c.AdjustBetAmounts(amount);

        // Fund sender
        vm.deal(sender, amount);

        // Call wager as sender (EOA)
        vm.prank(sender, sender);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("wager()"));

        // The assertion: if wager succeeded, the mapping reflects the amount; otherwise it remains 0
        bool playerHasWagered = c.hasPlayerWagered(sender);
        // If wager succeeded, mapping should be true; if not, false
        // Since the bug deletes wagers[msg.sender] = msg.value, on buggy version it will remain false even on success
        // On reference, it will be true on success
        assertTrue(playerHasWagered == success, "wager mapping should reflect wager success");
    }
}

